#!/bin/bash
# End-to-end reproduction inside the container: no downloads are needed
# (synthetic instances are generated by the evaluators). Scores the reference
# certifier (method/certifiers/noisy_ht.py) on the canonical/train slice and
# on the held-out test.

set -euo pipefail

ROOT="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
cd "${ROOT}"

echo "=== Noisy HT reproduction ==="
bash scripts/download.sh
bash scripts/evaluate.sh
bash scripts/evaluate_train.sh
bash scripts/evaluate_test.sh
echo "=== Reproduction complete: scoring/scores.json, scores_train.json, scores_test.json ==="
